import{c as s,o as e,a5 as n,j as t,k as i,g as l}from"./chunks/framework.BXgPSHrU.js";const o=["href"],c=JSON.parse('{"title":"Vibe Coding 實戰指南：PIV 框架與三大黃金法則","description":"","frontmatter":{},"headers":[],"relativePath":"project/vibe-coding-piv-framework.md","filePath":"project/vibe-coding-piv-framework.md","lastUpdated":1765331424000}'),p={name:"project/vibe-coding-piv-framework.md"},g=Object.assign(p,{setup(r){return(d,a)=>(e(),s("div",null,[a[0]||(a[0]=n(`<h1 id="vibe-coding-實戰指南-piv-框架與三大黃金法則" tabindex="-1">Vibe Coding 實戰指南：PIV 框架與三大黃金法則 <a class="header-anchor" href="#vibe-coding-實戰指南-piv-框架與三大黃金法則" aria-label="Permalink to &quot;Vibe Coding 實戰指南：PIV 框架與三大黃金法則&quot;">​</a></h1><blockquote><p>當 AI 成為你的 Pair Programming 夥伴，你需要的不是更多技術，而是更好的協作框架。</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2025 年 12 月</p><hr><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Vibe Coding 是一種與 AI 編程助手（如 Claude Code、GitHub Copilot）協作開發的新型態工作模式。你描述意圖，AI 產出程式碼，聽起來很美好——但實際操作時，許多開發者會發現：</p><ul><li>AI 經常「過度發揮」，做了你沒要的東西</li><li>產出的程式碼不確定能不能用</li><li>來回修改比自己寫還累</li></ul><p>問題不在 AI 不夠聰明，而在於<strong>我們缺乏一套與 AI 協作的方法論</strong>。</p><p>本文將介紹 <strong>PIV 框架</strong>與<strong>三大黃金法則</strong>，幫助你在 Vibe Coding 中保持掌控感，同時最大化 AI 的生產力。</p><hr><h2 id="piv-框架-與-ai-協作的基本節奏" tabindex="-1">PIV 框架：與 AI 協作的基本節奏 <a class="header-anchor" href="#piv-框架-與-ai-協作的基本節奏" aria-label="Permalink to &quot;PIV 框架：與 AI 協作的基本節奏&quot;">​</a></h2><p>PIV 是三個階段的縮寫：<strong>Planning → Implementation → Validation</strong>。</p><p>這不是什麼新概念，但在 Vibe Coding 的情境下，它的重要性被大幅放大——因為 AI 不會幫你思考「該不該做」，它只會執行「怎麼做」。</p><h3 id="p-planning-規劃" tabindex="-1">P - Planning（規劃） <a class="header-anchor" href="#p-planning-規劃" aria-label="Permalink to &quot;P - Planning（規劃）&quot;">​</a></h3><p>在下指令給 AI 之前，先問自己：</p><ul><li><strong>輸入是什麼？</strong> 這個功能接收什麼參數或資料？</li><li><strong>輸出是什麼？</strong> 預期產生什麼結果？</li><li><strong>邊界條件？</strong> 空值、錯誤輸入、極端情況怎麼處理？</li><li><strong>這個功能的範圍？</strong> 只做這件事，不多不少。</li></ul><h4 id="❌-常見錯誤" tabindex="-1">❌ 常見錯誤 <a class="header-anchor" href="#❌-常見錯誤" aria-label="Permalink to &quot;❌ 常見錯誤&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「幫我做一個用戶登入功能」</span></span></code></pre></div><p>這種模糊指令會讓 AI 自行腦補大量細節，產出可能包含你不需要的 OAuth、記住我、密碼重設等功能。</p><h4 id="✅-較好的做法" tabindex="-1">✅ 較好的做法 <a class="header-anchor" href="#✅-較好的做法" aria-label="Permalink to &quot;✅ 較好的做法&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「實作一個登入函數：</span></span>
<span class="line"><span>- 輸入：email 和 password</span></span>
<span class="line"><span>- 驗證：檢查 email 格式，password 至少 8 字元</span></span>
<span class="line"><span>- 成功回傳 user 物件，失敗拋出 ValidationError</span></span>
<span class="line"><span>- 不需要實作資料庫連接，用 dependency injection」</span></span></code></pre></div><p><strong>規劃階段的時間投入，會在後續省下數倍的修改時間。</strong></p><hr><h3 id="i-implementation-實作" tabindex="-1">I - Implementation（實作） <a class="header-anchor" href="#i-implementation-實作" aria-label="Permalink to &quot;I - Implementation（實作）&quot;">​</a></h3><p>這是 AI 發揮的階段。你的角色轉變為<strong>觀察者與引導者</strong>：</p><ul><li><strong>觀察 AI 的思路</strong>：它是否理解你的意圖？</li><li><strong>適時中斷</strong>：發現方向錯誤就停下來，補充資訊</li><li><strong>保持小步迭代</strong>：一次只做一件事（詳見後文）</li></ul><p>這個階段的重點是「讓 AI 做事，但保持監督」。</p><hr><h3 id="v-validation-驗證" tabindex="-1">V - Validation（驗證） <a class="header-anchor" href="#v-validation-驗證" aria-label="Permalink to &quot;V - Validation（驗證）&quot;">​</a></h3><p><strong>這是 Vibe Coding 中最容易被忽略，卻最關鍵的環節。</strong></p><p>AI 產出的程式碼看起來很專業，語法正確，結構漂亮——但這不代表它是對的。</p><p>驗證的方式包括：</p><table tabindex="0"><thead><tr><th>驗證方法</th><th>適用情境</th></tr></thead><tbody><tr><td>執行測試</td><td>有寫測試的情況（推薦！）</td></tr><tr><td><code>git diff</code></td><td>審查 AI 改了什麼</td></tr><tr><td>實際執行</td><td>手動測試功能</td></tr><tr><td>Code Review</td><td>逐行閱讀理解邏輯</td></tr><tr><td>問 AI 解釋</td><td>「解釋這段程式碼在做什麼」</td></tr></tbody></table><h4 id="🚨-警告" tabindex="-1">🚨 警告 <a class="header-anchor" href="#🚨-警告" aria-label="Permalink to &quot;🚨 警告&quot;">​</a></h4><p><strong>不驗證就接受 = 埋地雷。</strong></p><p>AI 產生的程式碼可能包含：</p><ul><li>隱微的邏輯錯誤</li><li>安全漏洞</li><li>不符合專案慣例的寫法</li><li>過度設計或效能問題</li></ul><p>養成習慣：<strong>每次 AI 產出後，至少做一種驗證。</strong></p><hr><h2 id="三大黃金法則" tabindex="-1">三大黃金法則 <a class="header-anchor" href="#三大黃金法則" aria-label="Permalink to &quot;三大黃金法則&quot;">​</a></h2><p>在 PIV 框架之內，以下三個法則能讓你的 Vibe Coding 更加順暢。</p><h3 id="法則一-small-steps-小步迭代" tabindex="-1">法則一：Small Steps（小步迭代） <a class="header-anchor" href="#法則一-small-steps-小步迭代" aria-label="Permalink to &quot;法則一：Small Steps（小步迭代）&quot;">​</a></h3><blockquote><p>每次只請 AI 做一件小事。</p></blockquote><h4 id="為什麼重要" tabindex="-1">為什麼重要？ <a class="header-anchor" href="#為什麼重要" aria-label="Permalink to &quot;為什麼重要？&quot;">​</a></h4><ul><li><strong>出錯容易定位</strong>：改動小，問題範圍就小</li><li><strong>審查更輕鬆</strong>：<code>git diff</code> 只有幾十行，而不是幾百行</li><li><strong>回退成本低</strong>：不滿意？<code>git checkout</code> 重來</li></ul><h4 id="實踐方式" tabindex="-1">實踐方式 <a class="header-anchor" href="#實踐方式" aria-label="Permalink to &quot;實踐方式&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ❌ 不好的做法</span></span>
<span class="line"><span>「幫我實作完整的購物車功能，包含新增、刪除、修改數量、計算總價、套用折扣碼」</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ✅ 好的做法</span></span>
<span class="line"><span>「先實作購物車的新增商品功能」</span></span>
<span class="line"><span>（完成、驗證、commit）</span></span>
<span class="line"><span>「接著實作刪除商品功能」</span></span>
<span class="line"><span>（完成、驗證、commit）</span></span>
<span class="line"><span>...</span></span></code></pre></div><p><strong>口訣：一個 prompt，一個功能，一個 commit。</strong></p><hr><h3 id="法則二-tdd-test-first-測試先行" tabindex="-1">法則二：TDD / Test First（測試先行） <a class="header-anchor" href="#法則二-tdd-test-first-測試先行" aria-label="Permalink to &quot;法則二：TDD / Test First（測試先行）&quot;">​</a></h3><blockquote><p>讓 AI 先寫測試，再寫實作。</p></blockquote><h4 id="為什麼在-vibe-coding-中特別有效" tabindex="-1">為什麼在 Vibe Coding 中特別有效？ <a class="header-anchor" href="#為什麼在-vibe-coding-中特別有效" aria-label="Permalink to &quot;為什麼在 Vibe Coding 中特別有效？&quot;">​</a></h4><ol><li><strong>測試即規格</strong>：測試案例就是你對功能的精確描述，AI 不用猜你要什麼</li><li><strong>自動驗證</strong>：有了測試，Validation 階段變成一鍵執行</li><li><strong>防止過度設計</strong>：AI 只需要讓測試通過，不會亂加功能</li></ol><h4 id="實踐方式-1" tabindex="-1">實踐方式 <a class="header-anchor" href="#實踐方式-1" aria-label="Permalink to &quot;實踐方式&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 第一步：請 AI 寫測試</span></span>
<span class="line"><span>「幫我寫測試案例，驗證 calculateTotal 函數：</span></span>
<span class="line"><span>- 空購物車回傳 0</span></span>
<span class="line"><span>- 單一商品回傳該商品價格 × 數量</span></span>
<span class="line"><span>- 多商品回傳加總」</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 第二步：確認測試符合預期</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 第三步：請 AI 實作</span></span>
<span class="line"><span>「現在實作 calculateTotal 讓測試通過」</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 第四步：執行測試驗證</span></span></code></pre></div><p><strong>測試就是你和 AI 之間的契約。</strong></p><hr><h3 id="法則三-yagni-不做不需要的事" tabindex="-1">法則三：YAGNI（不做不需要的事） <a class="header-anchor" href="#法則三-yagni-不做不需要的事" aria-label="Permalink to &quot;法則三：YAGNI（不做不需要的事）&quot;">​</a></h3><blockquote><p>You Ain&#39;t Gonna Need It — 你不會需要它的。</p></blockquote><h4 id="為什麼重要-1" tabindex="-1">為什麼重要？ <a class="header-anchor" href="#為什麼重要-1" aria-label="Permalink to &quot;為什麼重要？&quot;">​</a></h4><p>AI 很容易「過度發揮」：</p><ul><li>你要一個簡單函數，它給你一個完整的 class 架構</li><li>你要處理一種情況，它幫你預留了十種擴展點</li><li>你沒提到錯誤處理，它自作主張加了複雜的 retry 機制</li></ul><p>這些「貼心」的設計往往造成：</p><ul><li>程式碼變複雜，難以維護</li><li>引入你不理解的邏輯</li><li>增加測試負擔</li></ul><h4 id="實踐方式-2" tabindex="-1">實踐方式 <a class="header-anchor" href="#實踐方式-2" aria-label="Permalink to &quot;實踐方式&quot;">​</a></h4><p>在 prompt 中明確約束：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「只實作這個功能，不要加額外的擴展設計」</span></span>
<span class="line"><span>「保持簡單，不需要考慮未來的擴展性」</span></span>
<span class="line"><span>「不要加入我沒提到的功能」</span></span></code></pre></div><p><strong>口訣：現在不需要的，現在就不做。</strong></p><hr><h2 id="框架與法則的關係" tabindex="-1">框架與法則的關係 <a class="header-anchor" href="#框架與法則的關係" aria-label="Permalink to &quot;框架與法則的關係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>法則</th><th>對應 PIV 階段</th><th>作用</th></tr></thead><tbody><tr><td>Small Steps</td><td>貫穿整體</td><td>控制每次迭代的範圍</td></tr><tr><td>TDD</td><td>P + V</td><td>規劃時定義規格，驗證時自動檢查</td></tr><tr><td>YAGNI</td><td>P</td><td>限制範圍，避免過度設計</td></tr></tbody></table><p><strong>PIV 是框架骨幹，三大法則是執行戰術。</strong> 兩者搭配，才能在 Vibe Coding 中從從容容，游刃有餘。</p><hr><h2 id="實戰範例" tabindex="-1">實戰範例 <a class="header-anchor" href="#實戰範例" aria-label="Permalink to &quot;實戰範例&quot;">​</a></h2><p>假設你要實作一個「計算訂單折扣」的功能：</p><h3 id="step-1-planning" tabindex="-1">Step 1: Planning <a class="header-anchor" href="#step-1-planning" aria-label="Permalink to &quot;Step 1: Planning&quot;">​</a></h3><p>思考並寫下：</p><ul><li>輸入：訂單金額（number）、折扣碼（string）</li><li>輸出：折扣後金額（number）</li><li>規則：<code>SAVE10</code> 打九折、<code>SAVE20</code> 打八折、無效碼不打折</li><li>範圍：只做折扣計算，不處理折扣碼的驗證來源</li></ul><h3 id="step-2-test-first" tabindex="-1">Step 2: Test First <a class="header-anchor" href="#step-2-test-first" aria-label="Permalink to &quot;Step 2: Test First&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「請寫測試案例：</span></span>
<span class="line"><span>1. 無折扣碼，回傳原價</span></span>
<span class="line"><span>2. SAVE10 折扣碼，回傳 90%</span></span>
<span class="line"><span>3. SAVE20 折扣碼，回傳 80%</span></span>
<span class="line"><span>4. 無效折扣碼，回傳原價</span></span>
<span class="line"><span>只測試這四種情況，不要加其他的。」</span></span></code></pre></div><h3 id="step-3-implementation" tabindex="-1">Step 3: Implementation <a class="header-anchor" href="#step-3-implementation" aria-label="Permalink to &quot;Step 3: Implementation&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「實作 applyDiscount(amount, discountCode) 讓測試通過。</span></span>
<span class="line"><span>保持簡單，不要預留其他折扣類型的擴展。」</span></span></code></pre></div><h3 id="step-4-validation" tabindex="-1">Step 4: Validation <a class="header-anchor" href="#step-4-validation" aria-label="Permalink to &quot;Step 4: Validation&quot;">​</a></h3><ul><li>執行測試 ✅</li><li><code>git diff</code> 確認改動 ✅</li><li>Commit ✅</li></ul><hr><h2 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to &quot;總結&quot;">​</a></h2><p>Vibe Coding 的成功關鍵不是更厲害的 AI，而是<strong>更好的人機協作方法</strong>。</p><p>記住這個口訣：</p><blockquote><p><strong>PIV 打底，小步走，測試領，不貪多。</strong></p></blockquote><ul><li><strong>P</strong>lanning：想清楚再動手</li><li><strong>I</strong>mplementation：讓 AI 做，你監督</li><li><strong>V</strong>alidation：驗證後才接受</li><li><strong>Small Steps</strong>：一次一小步</li><li><strong>TDD</strong>：測試先行</li><li><strong>YAGNI</strong>：不做多餘的事</li></ul><p>掌握這套方法論，你會發現 AI 不再是難以控制的黑盒子，而是一個高效可靠的開發夥伴。</p><hr><h2 id="🎁-bonus-實戰配置檔案" tabindex="-1">🎁 Bonus：實戰配置檔案 <a class="header-anchor" href="#🎁-bonus-實戰配置檔案" aria-label="Permalink to &quot;🎁 Bonus：實戰配置檔案&quot;">​</a></h2><p>想要在實際開發中應用 PIV 框架和三大法則？我準備了一份 <strong>Claude Code 開發規則配置檔</strong>，你可以直接用在與 AI 協作時：</p>`,94)),t("p",null,[t("a",{href:i(l)("/docs/claude.md"),download:"CLAUDE.md"},"📥 下載 Claude Code 開發規則",8,o)]),a[1]||(a[1]=n('<p>這份配置檔包含：</p><ul><li>PIV 框架的詳細執行步驟</li><li>三大黃金法則的實踐指南</li><li>溝通規則與禁止事項</li><li>可直接套用的開發口訣</li></ul><p>將這份規則提供給你的 AI 助手（如 Claude、ChatGPT），能讓協作更加順暢高效。</p><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><a href="https://www.amazon.com/Test-Driven-Development-Kent-Beck/dp/0321146530" target="_blank" rel="noreferrer">Test-Driven Development by Example - Kent Beck</a></li><li><a href="https://pragprog.com/titles/tpp20/the-pragmatic-programmer-20th-anniversary-edition/" target="_blank" rel="noreferrer">The Pragmatic Programmer</a></li><li><a href="https://docs.anthropic.com" target="_blank" rel="noreferrer">Claude Code 官方文件</a></li></ul>',6))]))}});export{c as __pageData,g as default};
